import boto3
from botocore.exceptions import NoCredentialsError, PartialCredentialsError

def extract_receipt_data(image_path):
    client = boto3.client('textract')

    try:
        with open(image_path, "rb") as image:
            image_bytes = image.read()

        response = client.analyze_expense(Document={'Bytes': image_bytes})

        merchant = None
        tax = None
        total = None
        items = []

        for document in response.get('ExpenseDocuments', []):
            for line_item_group in document.get('LineItemGroups', []):
                for line_item in line_item_group.get('LineItems', []):
                    if line_item.get('LineItemExpenseFields'):
                        for field in line_item['LineItemExpenseFields']:
                            if field.get('Type'):
                                if field['Type']['Text'] == 'DESCRIPTION':
                                    items.append(field['ValueDetection']['Text'])
                                if field['Type']['Text'] == 'PRICE':
                                    items[-1] += f" - {field['ValueDetection']['Text']}"
                            if field.get('LabelDetection'):
                                if field['LabelDetection']['Text'] == 'TAX':
                                    tax = field['ValueDetection']['Text']
                                if field['LabelDetection']['Text'] == 'TOTAL':
                                    total = field['ValueDetection']['Text']
                        merchant = document.get('SummaryFields', [])[0].get('ValueDetection', {}).get('Text', None)

        return {
           'merchant': merchant,
            'tax': tax,
            'total': total,
            'items': items
        }

    except (NoCredentialsError, PartialCredentialsError) as e:
        print(f"AWS credential error: {e}")
        return None
